#!/usr/bin/env python3
"""
Applies the বিশ্বাস IQ AI rename + logo to dashboard.html.
Only 6 exact edits are made; every other byte of the file is left untouched.

Usage (from the folder that holds dashboard.html):
    py -3.14 patch_dashboard.py            # or: python patch_dashboard.py path/to/dashboard.html
A backup is written to dashboard.backup.html first.
"""
import re, sys, shutil
from pathlib import Path

NAV_LOGO_B64 = ""

path = Path(sys.argv[1] if len(sys.argv) > 1 else "dashboard.html")
if not path.exists():
    sys.exit(f"Cannot find {path}. Run this from the folder that contains dashboard.html.")

raw = path.read_bytes().decode("utf-8")
crlf = "\r\n" in raw
src = raw.replace("\r\n", "\n")

if "brand-logo" in src:
    sys.exit("Already patched - nothing to do.")

def once(text, pattern, repl, label, flags=0):
    new, n = re.subn(pattern, lambda m: repl(m) if callable(repl) else repl, text, count=0, flags=flags)
    if n != 1:
        sys.exit(f"ABORTED: expected exactly 1 match for {label}, found {n}. File not modified.")
    return new

CSS = '''
  /* ---------- brand logo + Bengali wordmark ---------- */
  .brand-wrap { display: flex; align-items: center; gap: 12px; }
  .brand-logo {
    width: 32px; height: 32px; display: block; object-fit: cover;
    border: 1px solid var(--line-2); border-radius: 2px;
  }
  /* Bengali script: letter-spacing would pull conjuncts apart */
  .bn { font-family: "Noto Sans Bengali", var(--sans); letter-spacing: 0; text-transform: none; }
  .assistant-row .assistant-role { font-family: var(--mono), "Noto Sans Bengali", sans-serif; }
  .assistant-row.sys .assistant-role { letter-spacing: 0; }
'''

BRAND = '''<div class="brand-wrap">
    <img class="brand-logo" src="data:image/jpeg;base64,%s" alt="বিশ্বাস IQ AI logo">
    <div class="brand">
      <span class="wordmark"><span class="bn">বিশ্বাস</span> IQ AI</span>
      <span class="brand-sub">Ring Detection Console</span>
    </div>
  </div>''' % NAV_LOGO_B64

out = src
out = once(out, r"<title>TrustNet — Ring Detection Console</title>",
           '<title>বিশ্বাস IQ AI — Ring Detection Console</title>\n'
           '<link rel="icon" type="image/jpeg" href="data:image/jpeg;base64,%s">' % NAV_LOGO_B64,
           "<title>")
out = once(out, r"&family=JetBrains\+Mono:wght@400;500;700&display=swap",
           "&family=JetBrains+Mono:wght@400;500;700&family=Noto+Sans+Bengali:wght@500;700&display=swap",
           "Google Fonts link")
out = once(out, r"\n  \.conn \{", lambda m: CSS + "\n  .conn {", "CSS insertion point (.conn)")
out = once(out,
           r'<div class="brand">\s*<span class="wordmark">TrustNet</span>\s*'
           r'<span class="brand-sub">Ring Detection Console</span>\s*</div>',
           BRAND, "topbar brand block")
out = once(out, r"tag\.textContent = role === 'user' \? 'You' : 'TrustNet';",
           "tag.textContent = role === 'user' ? 'You' : 'বিশ্বাস IQ AI';",
           "assistant label")

shutil.copyfile(path, path.with_name(path.stem + ".backup" + path.suffix))
if crlf:
    out = out.replace("\n", "\r\n")
path.write_bytes(out.encode("utf-8"))
print("Patched", path, "- backup saved as", path.stem + ".backup" + path.suffix)